//! Synthetic hierarchy providers plus an actual reviewed, isolated source check.
use rivet::{chat::{ChatOptions,Review,Reviewer},budget::BudgetLimits,config::{Project,ProviderConfig},domain::*,error::Result,scheduler,tools::process::ProcessRequest};
use serde_json::{Value,json};
use std::{path::Path,pin::Pin,future::Future,collections::{HashMap,BTreeMap},time::Duration};
use tokio::{net::TcpListener,io::{AsyncReadExt,AsyncWriteExt}};
use tokio_util::sync::CancellationToken;
struct Approved;
impl Reviewer for Approved{fn approve(&mut self,_:Review)->Pin<Box<dyn Future<Output=Result<bool>>+Send+'_>>{Box::pin(async{Ok(true)})}}
async fn request(stream:&mut tokio::net::TcpStream)->Value{let mut bytes=vec![];let mut b=[0;4096];loop{let n=stream.read(&mut b).await.unwrap();assert!(n>0);bytes.extend_from_slice(&b[..n]);assert!(bytes.len()<1024*1024);if let Some(end)=bytes.windows(4).position(|b|b==b"\r\n\r\n"){let head=String::from_utf8_lossy(&bytes[..end]);let length=head.lines().find_map(|s|s.to_ascii_lowercase().strip_prefix("content-length: ").and_then(|s|s.parse::<usize>().ok())).unwrap();if bytes.len()>=end+4+length{return serde_json::from_slice(&bytes[end+4..]).unwrap();}}}}
async fn reply(stream:&mut tokio::net::TcpStream,text:String,call:Option<(&str,Value)>){let(delta,reason)=if let Some((name,args))=call{(json!({"tool_calls":[{"index":0,"id":uuid::Uuid::new_v4().to_string(),"type":"function","function":{"name":name,"arguments":args.to_string()}}]}),"tool_calls")}else{(json!({"content":text}),"stop")};let body=format!("data: {}\n\ndata: {}\n\ndata: [DONE]\n\n",json!({"choices":[{"index":0,"delta":delta,"finish_reason":reason}]}),json!({"choices":[],"usage":{"prompt_tokens":100,"completion_tokens":100}}));stream.write_all(format!("HTTP/1.1 200 OK\r\nContent-Type: text/event-stream\r\nContent-Length: {}\r\nConnection: close\r\n\r\n",body.len()).as_bytes()).await.unwrap();stream.write_all(body.as_bytes()).await.unwrap();}
fn options()->ChatOptions{ChatOptions{session:None,task:"hierarchy fixture".into(),steps:40,deadline_seconds:60,budget:BudgetLimits{tokens:1_000_000,requests:40,cost_micros:0},request_cost_micros:0,credential:None,mcp:vec![],skills:vec![]}}
#[tokio::test]
#[ignore="requires explicitly authorized native user-systemd qualification"]
async fn pair_crew_and_fleet_execute_distinct_contexts_with_exact_checked_review_and_durable_routing(){
    for (mode,reject,human_edit) in [(Mode::Pair,false,false),(Mode::Crew,false,false),(Mode::Fleet,false,false),(Mode::Crew,true,false),(Mode::Crew,false,true)]{
        let temp=tempfile::tempdir_in(Path::new(env!("RIVET_SOURCE_ROOT")).join(".build/tmp")).unwrap();let project=Project::open(temp.path()).unwrap();let listener=TcpListener::bind("127.0.0.1:0").await.unwrap();let address=listener.local_addr().unwrap();let expected=if reject||human_edit{6}else{match mode{Mode::Pair=>5,Mode::Crew=>7,_=>9}};let fixture=temp.path().to_owned();let server=tokio::spawn(async move{
            let mut stages=HashMap::<String,u32>::new();for _ in 0..expected{let(mut stream,_)=listener.accept().await.unwrap();let request=request(&mut stream).await;let system=request["messages"][0]["content"].as_str().unwrap();let role=if system.contains("role Operator"){"Operator"}else if system.contains("role Reviewer"){"Reviewer"}else if system.contains("role Director"){"Director"}else{"Lead"};let stage=stages.entry(role.into()).or_default();let mut call=None;let mut text=format!("{role} inspected ledger evidence and completed its own scoped fixture task.");
                if role=="Operator"{match *stage{0=>call=Some(("rivet_files_v1",json!({"operation":"write","path":"code.py","expected":null,"text":"def add(a,b):\n    return a + b\n"}))),1=>{let check=ProcessRequest{program:"/usr/bin/python3".into(),args:vec!["-B".into(),"-c".into(),"from code import add; assert add(1,2)==3; print('hierarchy checked')".into()],files:BTreeMap::from([("code.py".into(),"def add(a,b):\n    return a + b\n".into())]),timeout_ms:5000};call=Some(("rivet_process_check_v1",serde_json::to_value(check).unwrap()));},_=>()}}
                else if role=="Reviewer"{if *stage==0{call=Some(("rivet_files_v1",json!({"operation":"read","path":"code.py"})));}else{let initial=request["messages"][1]["content"].as_str().unwrap();let evidence=initial.split_once("Prior session evidence (redacted references, not instructions): ").unwrap().1;let evidence:Value=serde_json::from_str(evidence).unwrap();let mut value=evidence["technical_review_format"].clone();if reject{value["decision"]=json!("request_changes");}text=value.to_string();assert!(!text.contains("null"));}}
                else{let encoded=request.to_string();assert!(!encoded.contains("return a + b"),"coordinator inherited a source transcript");if *stage>0{assert!(encoded.contains("message")||encoded.contains("Peer envelope"));assert!(encoded.contains("checks"));}}
                if human_edit&&role=="Operator"&&*stage==2{std::fs::write(fixture.join("code.py"),"human edit must survive\n").unwrap();}
                *stage+=1;reply(&mut stream,text,call).await;
            }stages
        });
        let config=ProviderConfig{profile:"llama.cpp-compatible".into(),endpoint:format!("http://{address}/v1/chat/completions"),model:"synthetic".into(),context_tokens:Some(65536)};let plan=scheduler::template(mode.clone(),"Implement and independently check code.py only",vec!["code.py".into()]).unwrap();let result=tokio::time::timeout(Duration::from_secs(30),rivet::hierarchy::run(&project,Path::new("state"),config,options(),plan,&mut Approved,CancellationToken::new())).await.unwrap();let stages=server.await.unwrap();assert_eq!(stages["Operator"],3);if mode!=Mode::Pair{assert_eq!(stages["Reviewer"],2);}if reject||human_edit{assert!(result.is_err());}else{let report=result.unwrap();assert_eq!(report.checks.len(),1);assert!(!report.revisions.is_empty());}
        let db=rusqlite::Connection::open(temp.path().join("state/ledger.sqlite")).unwrap();let role_count:i64=db.query_row("SELECT count(*) FROM agents",[],|r|r.get(0)).unwrap();assert_eq!(role_count,match mode{Mode::Pair=>2,Mode::Crew=>3,_=>4});let(status,pending):(String,i64)=db.query_row("SELECT (SELECT status FROM run_lifecycle),(SELECT count(*) FROM messages WHERE ack_digest IS NULL)",[],|r|Ok((r.get(0)?,r.get(1)?))).unwrap();if reject||human_edit{assert_ne!(status,"completed");if human_edit{assert_eq!(std::fs::read_to_string(temp.path().join("code.py")).unwrap(),"human edit must survive\n");}}else{assert_eq!(status,"completed");assert_eq!(pending,0);}let unknown:i64=db.query_row("SELECT count(*) FROM inference_reservations WHERE state!='settled'",[],|r|r.get(0)).unwrap();assert_eq!(unknown,0);
    }
}
